-- Tags: long, no-msan
-- long: 640 000 rows of JSON, and the tag keeps the randomized index_granularity at 100 or above.
-- no-msan: about 500 s under MSan against 15 s in a debug build, too close to the 600 s per-test timeout;
-- the test still runs under ASan, UBSan and TSan.

-- Several whole-column and sub-object readers per task over big parts read by many tasks: multi-step PREWHERE, a filter
-- moved by the optimizer, ORDER BY with LIMIT, scattered keys, calls that cut granules, before and after a merge. The part
-- type, the granularity and the read settings come from the CI randomization; half of the queries pin many threads and
-- small tasks, the other half leaves them to it. Every line prints the row count and two
-- order-independent hashes of the result from the SHARED table and from the plain-type twin, and whether they are equal.

DROP TABLE IF EXISTS t; DROP TABLE IF EXISTS p;
CREATE TABLE t (x UInt64, json JSON(SHARED a UInt64, SHARED b Int32, SHARED s String, SHARED arr Array(UInt8), SHARED n Nullable(UInt32), SHARED lc LowCardinality(String), SHARED d.x UInt64, SHARED d.y String, max_dynamic_paths = 4)) ENGINE = MergeTree ORDER BY x;
CREATE TABLE p (x UInt64, json JSON(a UInt64, b Int32, s String, arr Array(UInt8), n Nullable(UInt32), lc LowCardinality(String), d.x UInt64, d.y String, max_dynamic_paths = 4)) ENGINE = MergeTree ORDER BY x;
SYSTEM STOP MERGES t; SYSTEM STOP MERGES p;
INSERT INTO t SELECT number, concat('{"a":', toString(number * 10), ',"b":', toString(toInt32(number % 1000) - 500), ',"s":"', repeat('s', number % 5), '","arr":', toString(range(number % 4)), if(number % 3 = 0, ',"n":null', concat(',"n":', toString(number % 100000))), ',"lc":"lc', toString(number % 7), '","d":{"x":', toString(number * 3), ',"y":"', repeat('y', number % 3), '"}', if(number % 2 = 0, concat(',"m":', toString(number)), ''), if(number % 11 = 0, concat(',"q":"q', toString(number % 13), '"'), ''), '}') FROM numbers(200000) SETTINGS max_threads = 1, max_insert_threads = 1;
INSERT INTO p SELECT number, concat('{"a":', toString(number * 10), ',"b":', toString(toInt32(number % 1000) - 500), ',"s":"', repeat('s', number % 5), '","arr":', toString(range(number % 4)), if(number % 3 = 0, ',"n":null', concat(',"n":', toString(number % 100000))), ',"lc":"lc', toString(number % 7), '","d":{"x":', toString(number * 3), ',"y":"', repeat('y', number % 3), '"}', if(number % 2 = 0, concat(',"m":', toString(number)), ''), if(number % 11 = 0, concat(',"q":"q', toString(number % 13), '"'), ''), '}') FROM numbers(200000) SETTINGS max_threads = 1, max_insert_threads = 1;
INSERT INTO t SELECT number, concat('{"a":', toString(number * 10), ',"b":', toString(toInt32(number % 1000) - 500), ',"s":"', repeat('s', number % 5), '","arr":', toString(range(number % 4)), if(number % 3 = 0, ',"n":null', concat(',"n":', toString(number % 100000))), ',"lc":"lc', toString(number % 7), '","d":{"x":', toString(number * 3), ',"y":"', repeat('y', number % 3), '"}', if(number % 2 = 0, concat(',"m":', toString(number)), ''), if(number % 11 = 0, concat(',"q":"q', toString(number % 13), '"'), ''), '}') FROM numbers(200000, 100000) SETTINGS max_threads = 1, max_insert_threads = 1;
INSERT INTO p SELECT number, concat('{"a":', toString(number * 10), ',"b":', toString(toInt32(number % 1000) - 500), ',"s":"', repeat('s', number % 5), '","arr":', toString(range(number % 4)), if(number % 3 = 0, ',"n":null', concat(',"n":', toString(number % 100000))), ',"lc":"lc', toString(number % 7), '","d":{"x":', toString(number * 3), ',"y":"', repeat('y', number % 3), '"}', if(number % 2 = 0, concat(',"m":', toString(number)), ''), if(number % 11 = 0, concat(',"q":"q', toString(number % 13), '"'), ''), '}') FROM numbers(200000, 100000) SETTINGS max_threads = 1, max_insert_threads = 1;
INSERT INTO t SELECT number, concat('{"a":', toString(number * 10), ',"b":', toString(toInt32(number % 1000) - 500), ',"s":"', repeat('s', number % 5), '","arr":', toString(range(number % 4)), if(number % 3 = 0, ',"n":null', concat(',"n":', toString(number % 100000))), ',"lc":"lc', toString(number % 7), '","d":{"x":', toString(number * 3), ',"y":"', repeat('y', number % 3), '"}', if(number % 2 = 0, concat(',"m":', toString(number)), ''), if(number % 11 = 0, concat(',"q":"q', toString(number % 13), '"'), ''), '}') FROM numbers(300000, 20000) SETTINGS max_threads = 1, max_insert_threads = 1;
INSERT INTO p SELECT number, concat('{"a":', toString(number * 10), ',"b":', toString(toInt32(number % 1000) - 500), ',"s":"', repeat('s', number % 5), '","arr":', toString(range(number % 4)), if(number % 3 = 0, ',"n":null', concat(',"n":', toString(number % 100000))), ',"lc":"lc', toString(number % 7), '","d":{"x":', toString(number * 3), ',"y":"', repeat('y', number % 3), '"}', if(number % 2 = 0, concat(',"m":', toString(number)), ''), if(number % 11 = 0, concat(',"q":"q', toString(number % 13), '"'), ''), '}') FROM numbers(300000, 20000) SETTINGS max_threads = 1, max_insert_threads = 1;
SELECT 'parts', count(), sum(rows) FROM system.parts WHERE database = currentDatabase() AND table = 't' AND active;
SELECT 'three parts: prewhere steps, concurrent', (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM t PREWHERE json.b % 7 = 0 WHERE json.n IS NOT NULL  SETTINGS enable_multiple_prewhere_read_steps = 1, max_threads = 16, merge_tree_min_rows_for_concurrent_read = 4096, merge_tree_min_bytes_for_concurrent_read = 1)) AS shared, (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM p PREWHERE json.b % 7 = 0 WHERE json.n IS NOT NULL  SETTINGS enable_multiple_prewhere_read_steps = 1, max_threads = 16, merge_tree_min_rows_for_concurrent_read = 4096, merge_tree_min_bytes_for_concurrent_read = 1)) AS plain, shared = plain;
SELECT 'three parts: prewhere steps', (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM t PREWHERE json.b % 7 = 0 WHERE json.n IS NOT NULL  SETTINGS enable_multiple_prewhere_read_steps = 1)) AS shared, (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM p PREWHERE json.b % 7 = 0 WHERE json.n IS NOT NULL  SETTINGS enable_multiple_prewhere_read_steps = 1)) AS plain, shared = plain;
SELECT 'three parts: moved filter, concurrent', (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM t WHERE json.b % 7 = 0 AND json.s != '' AND json.arr.size0 = 2  SETTINGS optimize_move_to_prewhere = 1, max_threads = 16, merge_tree_min_rows_for_concurrent_read = 4096, merge_tree_min_bytes_for_concurrent_read = 1)) AS shared, (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM p WHERE json.b % 7 = 0 AND json.s != '' AND json.arr.size0 = 2  SETTINGS optimize_move_to_prewhere = 1, max_threads = 16, merge_tree_min_rows_for_concurrent_read = 4096, merge_tree_min_bytes_for_concurrent_read = 1)) AS plain, shared = plain;
SELECT 'three parts: moved filter', (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM t WHERE json.b % 7 = 0 AND json.s != '' AND json.arr.size0 = 2  SETTINGS optimize_move_to_prewhere = 1)) AS shared, (SELECT (count(), sum(cityHash64(x, toString(json))), sum(cityHash64(a, b, s, arr, arr_size, n IS NULL, ifNull(n, 0), lc, dx, dy, d, m, q))) FROM (SELECT x, json, json.a AS a, json.b AS b, json.s AS s, json.arr AS arr, json.arr.size0 AS arr_size, json.n AS n, json.lc AS lc, json.d.x AS dx, json.d.y AS dy, json.^d AS d, toString(json.m) AS m, toString(json.q) AS q FROM p WHERE json.b % 7 = 0 AND json.s != '' AND json.arr.size0 = 2  SETTINGS optimize_move_to_prewhere = 1)) AS plain, shared = plain;
